			self:CloneLocalPlayerModel();
		end);
	else
		local tw = self:Tween(panel, {[LUAOBFUSACTOR_DECRYPT_STR_0("\196\139\126\74\81\244\133\104\79\82\210\152\124\79\69\246\139\111\68\88\229\147", "\54\134\234\29\33")]=1}, 0.15);
