		color = Color3.fromRGB(255, 60, 80);
	elseif (self.Config.Values.CrosshairColor == LUAOBFUSACTOR_DECRYPT_STR_0("\101\81\194\41\139\75", "\228\60\52\174\69")) then
		color = Color3.fromRGB(255, 220, 50);
